#include <mudock/type_alias.hpp>
#include <vector>
#include <cmath>

#define FLATTENED_2D(x, y, index_x) ((y) * index_x + (x))

#define GAUSS1_COEFF        (- 0.035579)
#define GAUSS2_COEFF        (- 0.005156)
#define REPULSION_COEFF     (0.840245)
#define HYDROPHOBIC_COEFF   (- 0.035069)
#define H_BOND_COEFF        (- 0.587439)
#define NROT_COEFF          (0.05846)

namespace mudock
{

    std::vector<fp_type> calc_dist_matrix(
        const fp_type* __restrict__ ligand_x,
        const fp_type* __restrict__ ligand_y,
        const fp_type* __restrict__ ligand_z,
        const size_t num_atoms)
    {

        /// High triangular matrix
        std::vector<fp_type> distance_matrix(num_atoms * num_atoms, 0);

        printf("Num atoms: %zu\n", num_atoms);

        for( size_t i = 0; i < num_atoms; i++) {
            for( size_t j = i + 1; j < num_atoms; j++) {
                size_t idx = FLATTENED_2D(i, j, num_atoms);
                distance_matrix[idx] = sqrt(
                    pow(ligand_x[i] - ligand_x[j], 2) +
                    pow(ligand_y[i] - ligand_y[j], 2) +
                    pow(ligand_z[i] - ligand_z[j], 2)
                );
            }   
        }

        return distance_matrix;
    }

    fp_type gauss1(const std::vector<fp_type> dst_mtx, const size_t mtx_size) {
        fp_type sum = 0;
        for( size_t i = 0; i < mtx_size; i++) {
            if(dst_mtx[i] != 0) sum += exp(- pow(dst_mtx[i] / 0.5, 2));
        }
        return sum;
    }

    fp_type gauss2(const std::vector<fp_type> dst_mtx, const size_t mtx_size) {
        fp_type sum = 0;
        for( size_t i = 0; i < mtx_size; i++) {
            if(dst_mtx[i] != 0) sum += exp(- pow((dst_mtx[i] - 3) / 2, 2));
        }
        return sum;
    }

    fp_type repulsion(const std::vector<fp_type> dst_mtx, const size_t mtx_size) {
        fp_type sum = 0;
        for( size_t i = 0; i < mtx_size; i++) {
            if(dst_mtx[i] != 0) sum += pow((dst_mtx[i] < 0) * dst_mtx[i], 2);
        }
        return sum;
    }

    fp_type score_function(const std::vector<fp_type> dst_mtx){
        fp_type g1 = gauss1(dst_mtx, dst_mtx.size());
        fp_type g2 = gauss2(dst_mtx, dst_mtx.size());
        fp_type rep = repulsion(dst_mtx, dst_mtx.size());

        /// Calc hydrophobic
        /// Calc hydrogen bond

        return GAUSS1_COEFF * g1 + GAUSS2_COEFF * g2 + REPULSION_COEFF * rep;
    }

} 

